entries[161386] = { ["name"] = "Erlernen", ["text"] = "Wirken in 3 sek.\nGewährt Pläne, mit denen Ihr in Eurer Garnison eine Schmiede bauen könnt.\n\nLevel 1\nErmöglicht die Herstellung von Erzeugnissen der Schmiedekunst und gewährt Arbeitsaufträge.\n\nLevel 2\nErmöglicht Anhängern mit der Eigenschaft 'Schmiedekunst', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\nLevel 3\nSchaltet Schmiedemissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig." }
entries[161387] = { ["name"] = "Erlernen", ["text"] = "Wirken in 3 sek.\nGewährt Pläne, mit denen Ihr in Eurer Garnison ein Alchemielabor bauen könnt.\n\nLevel 1\nErmöglicht die Herstellung von Erzeugnissen der Alchemie und gewährt Arbeitsaufträge.\n\nLevel 2\nErmöglicht Anhängern mit der Eigenschaft 'Alchemie', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\nLevel 3\nSchaltet Alchemiemissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig." }
entries[161388] = { ["name"] = "Erlernen", ["text"] = "Wirken in 3 sek.\nGewährt Pläne, mit denen Ihr in Eurer Garnison eine Gerberei bauen könnt.\n\nLevel 1\nErmöglicht die Herstellung von Erzeugnissen der Lederverarbeitung und gewährt Arbeitsaufträge.\n\nLevel 2\nErmöglicht Anhängern mit der Eigenschaft 'Lederverarbeitung', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\nLevel 3\nSchaltet Lederverarbeitungsmissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig." }
entries[161389] = { ["name"] = "Erlernen", ["text"] = "Wirken in 3 sek.\nGewährt Pläne, mit denen Ihr in Eurer Garnison ein Verzauberungsatelier bauen könnt.\n\nLevel 1\nErmöglicht die Herstellung von Gegenständen der Verzauberkunst und ermöglicht Charakteren ohne Verzauberfertigkeit, Gegenstände zu entzaubern. Gewährt außerdem Arbeitsaufträge.\n\nLevel 2\nErmöglicht Anhängern mit der Eigenschaft 'Verzauberkunst', hier zu arbeiten, was einen einzigartigen Bonus gewährt. Ermöglicht außerdem bis zu 14 Arbeitsaufträge gleichzeitig.\n\nLevel 3\nSchaltet Verzauberkunstmissionen frei und ermöglicht bis zu 21 Arbeitsaufträge gleichzeitig." }
