entries[162195] = { ["name"] = "Cybergenetische Mechbrille", ["text"] = "Wirken in 2 sek.\nTools: Gyromatischer Mikroregler\nReagenzien:\nGetriebefederteile (100)\nOptionale Reagenzien:\n[] (#50) , Kuppelschmiers Sperrzahnrad (#238)\nVerkäufer:\nNik Stahlringer\nZone:\nKriegsspeer\nKosten:\n1\n\nCybergenetische Mechbrille\nWird beim Anlegen gebunden\nEinzigartig anlegbar: Warlords - hergestellt (3)Kopf Kette\n8 Rüstung\n+5 [Beweglichkeit oder Intelligenz]+7 Ausdauer\nHaltbarkeit 100 / 100\nBenutzen: Ermöglicht Euch, in weite Entfernungen zu sehen.\n35\nBenötigt Ingenieurskunst von Draenor\n(1)" }
entries[162196] = { ["name"] = "Nachtsichtmechbrille", ["text"] = "Wirken in 2 sek.\nTools: Bogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nGetriebefederteile (100)\nOptionale Reagenzien:\n[] (#50) , Kuppelschmiers Sperrzahnrad (#238)\nVerkäufer:\nNik Stahlringer\nZone:\nKriegsspeer\nKosten:\n1\n\nNachtsichtmechbrille\nWird beim Anlegen gebunden\nEinzigartig anlegbar: Warlords - hergestellt (3)Kopf Leder\n6 Rüstung\n+5 [Beweglichkeit oder Intelligenz]+7 Ausdauer\nHaltbarkeit 100 / 100\nBenutzen: Ermöglicht Euch, in weite Entfernungen zu sehen.\n35\nBenötigt Ingenieurskunst von Draenor\n(1)" }
entries[162197] = { ["name"] = "Plasmamechbrille", ["text"] = "Wirken in 2 sek.\nTools: Gyromatischer Mikroregler\nReagenzien:\nGetriebefederteile (100)\nOptionale Reagenzien:\n[] (#50) , Kuppelschmiers Sperrzahnrad (#238)\nVerkäufer:\nNik Stahlringer\nZone:\nKriegsspeer\nKosten:\n1\n\nPlasmamechbrille\nWird beim Anlegen gebunden\nEinzigartig anlegbar: Warlords - hergestellt (3)Kopf Stoff\n3 Rüstung\n+5 Intelligenz\n+7 Ausdauer\nHaltbarkeit 100 / 100\nBenutzen: Ermöglicht Euch, in weite Entfernungen zu sehen.\n35\nBenötigt Ingenieurskunst von Draenor\n(1)" }
entries[162198] = { ["name"] = "Klingenschutzmechbrille", ["text"] = "Wirken in 2 sek.\nTools: Gyromatischer Mikroregler\nReagenzien:\nGetriebefederteile (100)\nOptionale Reagenzien:\n[] (#50) , Kuppelschmiers Sperrzahnrad (#238)\nVerkäufer:\nNik Stahlringer\nZone:\nKriegsspeer\nKosten:\n1\n\nKlingenschutzmechbrille\nWird beim Anlegen gebunden\nEinzigartig anlegbar: Warlords - hergestellt (3)Kopf Platte\n13 Rüstung\n+5 [Stärke oder Intelligenz]+7 Ausdauer\nHaltbarkeit 100 / 100\nBenutzen: Ermöglicht Euch, in weite Entfernungen zu sehen.\n35\nBenötigt Ingenieurskunst von Draenor\n(1)" }
entries[162199] = { ["name"] = "Eisenschredders Schredder", ["text"] = "Wirken in 3 sek.\nTools: Gyromatischer Mikroregler\nOhne Beruf:\nReagenzien:\nGetriebefederteile (100)\nOptionale Reagenzien:\n[] (#50) , Echteisenabzug (#239)\nVerkäufer:\nNik Stahlringer\nZone:\nKriegsspeer\nKosten:\n1\n\nEisenschredders Schredder\nWird beim Anlegen gebunden\nEinzigartig anlegbar: Warlords - hergestellt (3)Distanz Schusswaffe\n7 - 13 Schaden Geschwindigkeit 3.00\n(3.3 Schaden pro Sekunde)\n+5 Beweglichkeit\n+7 Ausdauer\nHaltbarkeit 120 / 120\n35\n\"Für Ingenieure ein Kunstwerk. Für Jäger ein Werkzeug für die Kunst des Tötens.\"" }
entries[162202] = { ["name"] = "Glotz' Raketenspalter", ["text"] = "Wirken in 2 sek.\nTools: Gyromatischer Mikroregler\nOhne Beruf:\nReagenzien:\nGetriebefederteile (20)\nVerkäufer:\nNik Stahlringer\nZone:\nKriegsspeer\nKosten:\n1\n\nGlotz' Raketenspalter\n35" }
entries[162203] = { ["name"] = "Megawattglühfaden", ["text"] = "Wirken in 2 sek.\nTools: Bogenlichtschraubenschlüssel\nOhne Beruf:\nReagenzien:\nGetriebefederteile (20)\nVerkäufer:\nNik Stahlringer\nZone:\nKriegsspeer\nKosten:\n1\n\nMegawattglühfaden\n35\n\"Alles ist besser unter Strom.\"" }
entries[162204] = { ["name"] = "Goblingleiterbausatz", ["text"] = "Wirken in 2 sek.\nTools: Bogenlichtschraubenschlüssel\nReagenzien:\nEchteisenerz (8), Prächtiges Fell (5)\nVerkäufer:\nZaren Hoffle\nGegenstand:\nIngenieurskunst von Draenor\nKosten:\n100\nZone:\nMondsturz\n\nVerkäufer:\nSean Fangleine\nGegenstand:\nIngenieurskunst von Draenor\nKosten:\n100\nZone:\nAshran\n\n(5)\nBenutzen: Verringert 2 Min. lang Eure Fallgeschwindigkeit. (3 Min Abklingzeit)" }
entries[162205] = { ["name"] = "Findels Plünderang", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer\nOhne Beruf:\nReagenzien:\nGetriebefederteile (50)\nVerkäufer:\nNik Stahlringer\nZone:\nKriegsspeer\nKosten:\n1\n\nFindels Plünderang\nWird bei Benutzung gebunden\nSpielzeug\nBenutzen: Sammelt die Beute von einer Leiche in der Nähe ein. Kann nur in Draenor verwendet werden. (3 Sek. Abklingzeit)" }
entries[162206] = { ["name"] = "Weltschrumpfer", ["text"] = "Wirken in 2 sek.\nTools: Gyromatischer Mikroregler\nReagenzien:\nGetriebefederteile (50)\nVerkäufer:\nNik Stahlringer\nZone:\nKriegsspeer\nKosten:\n1\n\nWeltschrumpfer\nSpielzeug\nBenutzen: Schrumpft die gesamte Welt 5 Min. lang oder bis Ihr angreift. (15 Min Abklingzeit)\nBenötigt Ingenieurskunst von Draenor\n(1)\n\"Übermäßiger Gebrauch kann zu dauerhafter Schrumpfung führen.\"" }
entries[162207] = { ["name"] = "Tarner 54", ["text"] = "Wirken in 2 sek.\nTools: Gyromatischer Mikroregler\nReagenzien:\nSchwarzfelserz (2), Echteisenerz (2), Nagrandpfeilkelch (2)\nVerkäufer:\nZaren Hoffle\nGegenstand:\nIngenieurskunst von Draenor\nKosten:\n100\nZone:\nMondsturz\n\nVerkäufer:\nSean Fangleine\nGegenstand:\nIngenieurskunst von Draenor\nKosten:\n100\nZone:\nAshran\n\n(5)\n35\n\"Unsichtbarkeit ist für Schwächlinge!\"" }
entries[162208] = { ["name"] = "Ultimatives gnomisches Armeemesser", ["text"] = "Wirken in 2 sek.\nReagenzien:\nGetriebefederteile (5)\nUltimatives gnomisches Armeemesser\n+10 Fertigkeit in Bergbau von Draenor.\n+10 Fertigkeit in Kräuterkunde von Draenor.\n+10 Fertigkeit in Kürschnerei von Draenor.\n\"Beinhaltet alles erforderliche Handwerkszeug.\"" }
entries[162209] = { ["name"] = "Mechanischer Axtschnabel", ["text"] = "Wirken in 3.5 sek.\nTools: Bogenlichtschraubenschlüssel\nOhne Beruf:\nReagenzien:\nGetriebefederteile (50)\nVerkäufer:\nNik Stahlringer\nZone:\nKriegsspeer\nKosten:\n1\n\nMechanischer Axtschnabel\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nBeschwört Euren mechanischen Tukan oder gibt ihn wieder frei.\n1 - 80 ( 80)" }
entries[162210] = { ["name"] = "Lebensechter mechanischer Frosteber", ["text"] = "Wirken in 3.5 sek.\nTools: Gyromatischer Mikroregler\nOhne Beruf:\nReagenzien:\nGetriebefederteile (50), Prächtiges Fell (40)\nVerkäufer:\nNik Stahlringer\nZone:\nKriegsspeer\nKosten:\n1\n\nLebensechter mechanischer Frosteber\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren lebensechten mechanischen Eber beschwören oder wieder freigeben.\n1 - 80 ( 80)" }
entries[162214] = { ["name"] = "Persönliches Hologramm", ["text"] = "Wirken in 2 sek.\nTools: Gyromatischer Mikroregler\nOhne Beruf:\nReagenzien:\nGetriebefederteile (50)\nVerkäufer:\nNik Stahlringer\nZone:\nKriegsspeer\nKosten:\n1\n\nPersönliches Hologramm\nWird bei Benutzung gebunden\nSpielzeug\nBenutzen: Erstellt 1 Min. lang ein temporäres Hologramm von Euch selbst. (5 Min Abklingzeit)\n\"Das Bild kann auf einige Emotes reagieren.\"" }
entries[162216] = { ["name"] = "Wurmlochzentrifuge", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nGetriebefederteile (50)\nVerkäufer:\nNik Stahlringer\nZone:\nKriegsspeer\nKosten:\n1\n\nWurmlochzentrifuge\nWird bei Benutzung gebunden\nSpielzeug\nBenutzen: Erschafft ein rotierendes Wurmloch, das der Ingenieur verwenden kann, um Draenor zu bereisen. (4 Std. Abklingzeit)\n34\nBenötigt Ingenieurskunst von Draenor\n(1)" }
entries[162217] = { ["name"] = "Wechselblaster", ["text"] = "Wirken in 2 sek.\nTools: Bogenlichtschraubenschlüssel\nOhne Beruf:\nReagenzien:\nGetriebefederteile (50), Temporaler Kristall\nVerkäufer:\nNik Stahlringer\nZone:\nKriegsspeer\nKosten:\n1\n\nWechselblaster\nWird bei Benutzung gebunden\nBenutzen: Tauscht Eure Position mit der eines anderen Gruppenmitglieds. Kann nicht im Kampf genutzt werden. (1 Min Abklingzeit)\n\"Achtung: Der Tausch mit einem Ziel, das einen neuralen Stummschalter verwendet, ist lebensgefährlich.\"" }
entries[162218] = { ["name"] = "Blingtron 5000", ["text"] = "Wirken in 2 sek.\nTools: Schmiedehammer , Gyromatischer Mikroregler\nReagenzien:\nGetriebefederteile (100)\nVerkäufer:\nNik Stahlringer\nZone:\nKriegsspeer\nKosten:\n1\n\nBlingtron 5000\nWird beim Aufheben gebunden\nSpielzeug\nBenutzen: Setzt den verbesserten Blingtron 5000 zusammen, einen wilden, aber großzügigen Roboter. Einerseits lässt er Spielercharakteren einmal am Tag kleine Präsente zukommen, anderseits bekämpft er andere Blingtron-Einheiten bis zum Tode. (4 Std. Abklingzeit)\nBenötigt Ingenieurskunst von Draenor\n(1)" }
