entries[162286] = { ["name"] = "Verzögerte Belagerungsbombe", ["text"] = "Unbegrenzte Reichweite\nSofort\nWirft eine Reihe von Bomben auf ein Ziel. Jede Bombe verursacht 8522 körperlichen Schaden und stößt Ziele innerhalb von 4.5 Metern zurück.\n\nDie Bomben bohren sich in den Boden und explodieren nach 30 Sek., wobei Ziele innerhalb von 9 Metern 9373 Feuerschaden erleiden." }
entries[162287] = { ["name"] = "Der lebende Berg", ["text"] = "Sofort\nTectus kann nicht getötet werden, solange er unter der Wirkung von 'Der lebende Berg' steht.\n\nEr wird regelmäßig Energie regenerieren. Je mehr Gesundheit er verliert, umso schneller wird er regenerieren.\n\nDie Kraft von 'Lebender Berg' wird aufgezehrt, wenn Tectus 'Tektonische Unruhe' kanalisiert. Das macht ihn anfällig für 'Zertrümmern'." }
entries[162288] = { ["name"] = "Zuwachs", ["text"] = "Sofort\nTectus absorbiert regelmäßig Erde in seinen Körper und erhöht damit den Schaden, den er verursacht, um 5%. Dieser Effekt ist stapelbar.\n\nWenn Tectus Schaden zugefügt wird, entfernt dies Stapel von 'Zuwachs'." }
