entries[162293] = { ["name"] = "Machterfüllte Waffen", ["text"] = "Sofort\nDie feurige Verbindung der Glutwölfe verstärkt die verzauberten Bewaffnungen. Diese fügen Spielercharakteren innerhalb von 6 Metern 9 Sek. lang alle 0.5 Sek. 426 Feuerschaden zu.\n\nAußerdem versprühen die Bewaffnungen 9 Sek. lang alle 0.5 Sek. geschmolzene Lava auf einen zufälligen Spielercharakter und fügen ihm 1038 Feuerschaden zu." }
entries[162295] = { ["name"] = "Schnitt bis auf die Knochen", ["text"] = "Nahkampfreichweite\nWirken in 1 sek.\nSchneidet das Ziel bis auf die Knochen, verursacht 150% Waffenschaden und erhöht den durch 'Schnitt bis auf die Knochen' erlittenen Schaden 10 Sek. lang um 10%.\nHeilung verringert diesen Effekt." }
